/* Story board result (storyresult.c PResCreate fills it, rank.c shows it). GC size 0x10. */
typedef struct SRankWork_s {
    s16 diff;          /* 0x0: GwPlayerConf[0].dif -- message offset */
    s16 totalRank;     /* 0x2: 0..4 from the summed board ranks -- message offset */
    s16 boardNum;      /* 0x4: boards played so far (GwCommon.storyNo after the increment) */
    s16 boardRank[5];  /* 0x6: rank per board (GwCommon.storyRank[]) */
} SRANKWORK;

